// Wire types for the skill-based engine (Mantle).
// Mirrors the backend contract in rasa/mantle/inspector.py — change in lock-step.
import { z } from "zod";

export const ProseSegmentSchema = z.object({
  text: z.string(),
  condition: z.string().nullable(),
});
export type ProseSegment = z.infer<typeof ProseSegmentSchema>;

export const ProseSectionSchema = z.object({
  type: z.literal("prose"),
  segments: z.array(ProseSegmentSchema),
});
export type ProseSection = z.infer<typeof ProseSectionSchema>;

export const OrderedBlockSectionSchema = z.object({
  type: z.literal("ordered_block"),
  block_id: z.string(),
});
export type OrderedBlockSection = z.infer<typeof OrderedBlockSectionSchema>;

export const SkillSectionSchema = z.discriminatedUnion("type", [
  ProseSectionSchema,
  OrderedBlockSectionSchema,
]);
export type SkillSection = z.infer<typeof SkillSectionSchema>;

// Steps are kept loose here: the graph mapper (utils/skill-flow-import) narrows
// per step `kind` and must tolerate kinds added on the backend later.
export const SkillStepSchema = z.looseObject({
  id: z.string(),
  kind: z.string(),
});
export type SkillStep = z.infer<typeof SkillStepSchema>;

export const SkillBlockSchema = z.object({
  // Fully-qualified ordered-block identifier ("<skill_id>__<block_id>"); the
  // bare block id is the key this block sits under in `Skill.blocks`.
  ordered_block_id: z.string(),
  complete_when: z.string().nullable(),
  steps: z.array(SkillStepSchema),
});
export type SkillBlock = z.infer<typeof SkillBlockSchema>;

export const SkillSchema = z.object({
  id: z.string(),
  name: z.string().nullable(),
  description: z.string().nullable(),
  is_default: z.boolean(),
  engine_managed: z.boolean(),
  disabled: z.boolean(),
  sections: z.array(SkillSectionSchema),
  blocks: z.record(z.string(), SkillBlockSchema),
  referenced_skills: z.array(z.string()),
  tool_names: z.array(z.string()),
  // Omitted from routing when true; absent on older backends.
  hidden: z.boolean().default(false),
});
export type Skill = z.infer<typeof SkillSchema>;

export const SkillCatalogSchema = z.record(z.string(), SkillSchema);
export type SkillCatalog = z.infer<typeof SkillCatalogSchema>;

export const BlockStatusSchema = z.object({
  status: z.enum(["active", "completed", "inactive"]),
});
export type BlockStatus = z.infer<typeof BlockStatusSchema>;

export const MemoryEntryStateSchema = z.object({
  value: z.unknown(),
  source: z.enum(["llm", "tool", "system"]).nullable(),
  scope: z.enum(["skill", "project", "system"]),
  description: z.string().nullable(),
});
export type MemoryEntryState = z.infer<typeof MemoryEntryStateSchema>;
export type MemorySource = NonNullable<MemoryEntryState["source"]>;

export const ActiveSkillRefSchema = z.object({
  skill_id: z.string().nullable(),
  // Fully-qualified id of the ordered block the engine is currently running.
  ordered_block_id: z.string(),
  step_id: z.string().nullable(),
});
export type ActiveSkillRef = z.infer<typeof ActiveSkillRefSchema>;

export const PendingSkillRefSchema = z.object({
  skill_id: z.string(),
  name: z.string().nullable(),
});
export type PendingSkillRef = z.infer<typeof PendingSkillRefSchema>;

export const ToolGateStatusSchema = z.object({
  active: z.boolean(),
});
export type ToolGateStatus = z.infer<typeof ToolGateStatusSchema>;

// One LLM completion call from the engine's ephemeral call log — the stopgap
// carrier for the GenAI span data until the span channel ships (ENG-3003).
export const LlmCallRecordSchema = z.object({
  id: z.string(),
  timestamp: z.number(),
  // Side-channel call label ("fact discovery"); null for main chat calls.
  purpose: z.string().nullable().default(null),
  request_model: z.string().nullable(),
  response_model: z.string().nullable(),
  input_tokens: z.number().nullable(),
  output_tokens: z.number().nullable(),
  latency_ms: z.number().nullable(),
  time_to_first_token_ms: z.number().nullable(),
  tool_names: z.array(z.string()),
  gated_tool_names: z.array(z.string()),
  response_tool_names: z.array(z.string()),
  prompt_messages: z.array(z.record(z.string(), z.unknown())).nullable(),
  response_messages: z.array(z.record(z.string(), z.unknown())).nullable(),
  is_error: z.boolean(),
  error_message: z.string().nullable(),
});
export type LlmCallRecord = z.infer<typeof LlmCallRecordSchema>;

export const SkillStateSchema = z.object({
  active_skill: ActiveSkillRefSchema.nullable(),
  // Parked precondition consumers. Absent on older backends.
  pending_skills: z.array(PendingSkillRefSchema).optional(),
  blocks: z.record(z.string(), BlockStatusSchema),
  evaluated_conditions: z.record(z.string(), z.boolean()),
  memory: z.record(z.string(), MemoryEntryStateSchema),
  // Both absent on older backends: default rather than fail the whole
  // skill_state parse.
  tools: z.record(z.string(), ToolGateStatusSchema).default({}),
  llm_calls: z.array(LlmCallRecordSchema).default([]),
});
export type SkillState = z.infer<typeof SkillStateSchema>;

/**
 * Parses a tracker payload's `skill_state` value, tolerating absence and
 * malformed data (both yield undefined) so a bad skill_state never breaks
 * the rest of the tracker update.
 */
export function parseSkillState(value: unknown): SkillState | undefined {
  const parsed = SkillStateSchema.safeParse(value);
  return parsed.success ? parsed.data : undefined;
}
